function TechnicianDailyDashboard({tech,day,truck,tasks,busy,openVisit,updateTask,show,readiness,saveIdentifiers,enterServiceTicket}:{tech:string;day:any;truck:any;tasks:any[];busy:boolean;openVisit:(v:any)=>void;updateTask:(id:string,status:string)=>void;show:(m:string)=>void;readiness?:any;saveIdentifiers?:(payload:any)=>void;enterServiceTicket?:(ticket?:string)=>void}){
  const visits=day?.visits||[],openTasks=(tasks||[]).filter((t:any)=>t.status!=='complete'),high=openTasks.filter((t:any)=>t.priority==='high').length;
  const department=String(day?.profile?.department||'IT').toLowerCase(),isService=department==='service',departmentLabel=isService?'SERVICE':'IT';
  const handoffCount=visits.filter((v:any)=>Number(v.visit_number)>1||String(v.visit_type||'').toLowerCase().includes('handoff')).length;
  const truckResult=truck?.result||{},truckReady=truck?.status==='completed'||day?.truck_check?.completed;
  const safetyChecks=Object.keys(truckResult?.truck||{}).filter(k=>truckResult.truck[k]===true).length;
  const itStock=isService?[]:[
    ['Sniper',1,Number(truckResult.it_sniper_qty??0)],['Ranger',1,Number(truckResult.it_ranger_qty??0)],
    ['Spotter',1,Number(truckResult.it_spotter_qty??0)],['Solar Spotter',1,Number(truckResult.it_solar_spotter_qty??0)],
    ['Recon Batteries',25,Number(truckResult.it_recon_battery_qty??0)],['AGM 12V 110Ah',4,Number(truckResult.it_agm_110ah_qty??0)],
    ['LiTime 12V 100Ah',2,Number(truckResult.it_litime_100ah_qty??0)],['AT&T SIM',1,Number(truckResult.it_att_sim_qty??0)],
    ['Verizon SIM',1,Number(truckResult.it_verizon_sim_qty??0)],['Vendera SIM',1,Number(truckResult.it_vendera_sim_qty??0)]
  ];
  const stockRecorded=isService||itStock.every((x:any)=>Object.prototype.hasOwnProperty.call(truckResult,({Sniper:'it_sniper_qty',Ranger:'it_ranger_qty',Spotter:'it_spotter_qty','Solar Spotter':'it_solar_spotter_qty','Recon Batteries':'it_recon_battery_qty','AGM 12V 110Ah':'it_agm_110ah_qty','LiTime 12V 100Ah':'it_litime_100ah_qty','AT&T SIM':'it_att_sim_qty','Verizon SIM':'it_verizon_sim_qty','Vendera SIM':'it_vendera_sim_qty'} as any)[x[0]]));
  const stockIssues=itStock.filter((x:any)=>x[2]<x[1]);
  const attention:any[]=[];
  if(!truckReady)attention.push({type:'Truck Inspection',issue:'Morning Truck Check is incomplete',related:'Your truck',priority:'HIGH'});
  if(truckReady&&safetyChecks<8)attention.push({type:'Truck Inspection',issue:'Truck inspection record needs review',related:'Your truck',priority:'HIGH'});
  stockIssues.forEach((x:any)=>attention.push({type:'Truck Stock',issue:x[0]+' — need '+(x[1]-x[2]),related:'Your truck',priority:'HIGH'}));
  openTasks.filter((t:any)=>t.priority==='high').forEach((t:any)=>attention.push({type:'Owner Task',issue:t.title,related:t.jobNumber||t.siteName||'Owner assignment',priority:'HIGH'}));
  visits.filter((v:any)=>!v.job_number||!v.customer_name||!v.site_name).forEach((v:any)=>attention.push({type:'Job Missing Info',issue:'Scheduled visit is missing required job information',related:v.job_number||'Visit',priority:'MEDIUM'}));
  const first=String(tech||day?.profile?.display_name||'Technician').split(' ')[0];
  const now=new Date();
  const taskStatus=(t:any)=>t.status==='in_progress'?'IN PROGRESS':t.status==='complete'?'COMPLETE':'NOT STARTED';
  const [identifiers,setIdentifiers]=useState<any>(()=>({
    sniperUnit:String(truckResult.it_sniper_unit||''),rangerUnit:String(truckResult.it_ranger_unit||''),spotterUnit:String(truckResult.it_spotter_unit||''),solarSpotterUnit:String(truckResult.it_solar_spotter_unit||''),
    attSim:String(truckResult.it_att_sim_number||''),verizonSim:String(truckResult.it_verizon_sim_number||''),venderaSim:String(truckResult.it_vendera_sim_number||'')
  }));
  const [ticketInput,setTicketInput]=useState('');
  const [trailerInspection,setTrailerInspection]=useState<any>(null);
  const [serviceInventory,setServiceInventory]=useState<any>(null);
  useEffect(()=>{if(isService)Promise.all([api.get('/api/tech/trailer-inspection'),api.get('/api/tech/truck-inventory')]).then(([t,i])=>{setTrailerInspection(t.data.inspection||null);setServiceInventory(i.data.inventory||null)}).catch(()=>{})},[isService]);
  useEffect(()=>setIdentifiers({sniperUnit:String(truckResult.it_sniper_unit||''),rangerUnit:String(truckResult.it_ranger_unit||''),spotterUnit:String(truckResult.it_spotter_unit||''),solarSpotterUnit:String(truckResult.it_solar_spotter_unit||''),attSim:String(truckResult.it_att_sim_number||''),verizonSim:String(truckResult.it_verizon_sim_number||''),venderaSim:String(truckResult.it_vendera_sim_number||'')}),[truck?.id,truck?.status]);
  const identifiersComplete=isService||Object.values(identifiers).every((v:any)=>String(v||'').trim().length>0);
  if(isService){
    const runReadiness=()=>{if(!readiness){show('Truck inspection is complete for today');return}const t=readiness.command?.type;if(t==='start')readiness.start();else if(t==='ready_to_complete')readiness.finish();else show('Continue the active Truck Inspection below to complete today’s readiness')};
    const runTrailerInspection=async()=>{const checks=[['tires','Are the trailer tires, tread and visible tire condition safe?'],['lights','Are all trailer lights and electrical connections working?'],['hitch','Is the hitch / coupler secured and locked correctly?'],['safetyChains','Are both safety chains attached and in safe condition?'],['jack','Is the trailer jack fully raised, secured and operating correctly?'],['breakaway','Is the breakaway cable / braking safety equipment connected and ready?'],['registration','Is the trailer plate / registration present and the trailer ready for road use?']] as const;const answers:any={};for(const[key,label]of checks){const yes=await cosConfirm(label);answers[key]=yes;if(!yes){try{const r=await api.post('/api/tech/trailer-inspection',{answers:{...Object.fromEntries(checks.map(([k])=>[k,false])),...answers}});setTrailerInspection(r.data);show('Trailer Inspection FAILED · correct the issue and reinspect before using the trailer')}catch(e:any){show(e?.message||'Trailer Inspection could not be saved')}return}}try{const r=await api.post('/api/tech/trailer-inspection',{answers});setTrailerInspection(r.data);show('Trailer Inspection PASSED · saved for today')}catch(e:any){show(e?.message||'Trailer Inspection could not be saved')}};
    const runTruckInventory=async()=>{const items=[['sniper','Sniper',1],['ranger','Ranger',1],['spotter','Spotter',1],['solarSpotter','Solar Spotter',1],['reconBatteries','Recon batteries',25],['agm110Ah','AGM 12V 110Ah batteries',4],['litime100Ah','LiTime 12V 100Ah batteries',2],['battery35Ah','12V 35Ah batteries',4],['attSim','AT&T SIM cards',1],['verizonSim','Verizon SIM cards',1],['venderaSim','Vendera SIM cards',1]] as const;const counts:any={};for(const[key,label,required]of items){const current=serviceInventory?.counts?.[key];const raw=await cosPrompt(label+' physically on truck now · required '+required,current===undefined?'':String(current));if(raw===null)return;const value=Number(raw);if(!Number.isInteger(value)||value<0){show('Enter a whole-number quantity for '+label);return}counts[key]=value}try{const r=await api.post('/api/tech/truck-inventory',{counts});setServiceInventory(r.data);show(r.data.status==='ready'?'Truck Inventory VERIFIED · required stock is on truck':'Truck Inventory SAVED · '+r.data.shortages.length+' shortage(s) shown; no request was created')}catch(e:any){show(e?.message||'Truck Inventory could not be saved')}};
    return <div className='service-command-home'><header><div><small>CAMERAS ONSITE · SERVICE TECH CHECK</small><h1>Good Morning, <i>{first}</i></h1><p>Complete daily readiness first, then open the assigned job and enter its MHelpDesk ticket.</p></div><span className={truckReady?'service-ready':'service-required'}>{truckReady?'TRUCK READY':'READINESS REQUIRED'}</span></header><form className='vision-ticket-entry' onSubmit={event=>{event.preventDefault();if(!busy&&truckReady&&ticketInput.trim())enterServiceTicket?.(ticketInput.trim());}}><label>Ticket number<input required value={ticketInput} onChange={event=>setTicketInput(event.target.value)} placeholder='Enter ticket number' inputMode='numeric'/></label><button disabled={busy||!truckReady} type='submit'>Open service check →</button>{!truckReady&&<small>Complete Truck Inspection first.</small>}</form><section className='service-command-grid'><button className={!truckReady?'required':''} onClick={runReadiness}><b>TRUCK INSPECTION</b><span>{truckReady?'Completed for today':'Complete the production Truck Check'}</span></button><button className={trailerInspection?.status==='failed'?'required':''} onClick={runTrailerInspection}><b>TRAILER INSPECTION</b><span>{trailerInspection?.status==='completed'?'Passed today · tap to reinspect':trailerInspection?.status==='failed'?'FAILED · correct issue and reinspect':'Independent daily trailer safety inspection'}</span></button><button className={serviceInventory?.status==='short'?'required':''} onClick={runTruckInventory}><b>TRUCK INVENTORY</b><span>{serviceInventory?.status==='ready'?'Verified today · required stock present':serviceInventory?.status==='short'?serviceInventory.shortages.length+' shortage(s) · tap to update':'Enter actual stock physically on the truck'}</span></button><button onClick={()=>show(visits.length?visits.length+' assigned job(s) are listed below.':'No assigned jobs today.')}><b>TODAY’S JOBS</b><span>{visits.length} assigned visit{visits.length===1?'':'s'}</span></button></section>{readiness&&<section className='it-readiness-block'><div><small>DAILY READINESS</small><h2>{readiness.command?.title||'Complete Truck Check'}</h2><p>{readiness.command?.section||'Truck Check'} · Jobs remain locked until readiness is complete.</p></div><div className='it-readiness-actions'>{readiness.command?.type==='start'&&<button disabled={busy} onClick={readiness.start}>START</button>}{readiness.command?.type==='yes_no'&&<><button disabled={busy} onClick={()=>readiness.answer(true)}>YES</button><button className='danger' disabled={busy} onClick={()=>readiness.answer(false)}>NO</button></>}{readiness.command?.type==='number'&&<button disabled={busy} onClick={readiness.enterNumber}>ENTER QUANTITY</button>}{readiness.command?.type==='text'&&<button disabled={busy} onClick={readiness.enterText}>ENTER IDENTIFIER</button>}{readiness.command?.type==='choice'&&(readiness.command?.choices||[]).map((x:string)=><button disabled={busy} key={x} onClick={()=>readiness.answer(x)}>{x.toUpperCase()}</button>)}{readiness.command?.type==='ready_to_complete'&&<button disabled={busy} onClick={readiness.finish}>FINISH</button>}</div></section>}<section className='service-jobs'><div className='it-panel-head'><h2>Today’s Assigned Jobs</h2><span>{visits.length}</span></div>{visits.length?visits.map((v:any)=><button className='service-job-card' key={v.visit_id} disabled={busy||!truckReady} onClick={()=>truckReady?openVisit(v):show('Complete Truck Inspection first')}><div><small>{v.scheduled_start?new Date(v.scheduled_start).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}):'SCHEDULED'} · {v.job_number}</small><b>{v.customer_name}</b><span>{v.site_name} · {v.visit_type}</span></div><strong>{truckReady?'OPEN ›':'LOCKED'}</strong></button>):<div className='it-empty'>No dispatched Service work today.</div>}</section></div>;
  }
  return <div className='it-command'>
    <aside className='it-side'><div className='it-brand'><img src='/resources/vision-eye-round.svg'/><div><b>CAMERAS<br/>ONSITE</b><small>OPERATIONS PLATFORM</small></div></div>
      <nav><button className='active'>⌂ <span>{departmentLabel} Dashboard</span></button><button onClick={()=>show('Today’s jobs are shown on this dashboard')}>▦ <span>Jobs</span></button><button onClick={()=>show('Today’s schedule is shown on this dashboard')}>▣ <span>Schedule</span></button><button onClick={()=>show('Open a scheduled job to enter Tech Check')}>◆ <span>Tech Check</span></button><button onClick={()=>show('Truck stock uses the production Truck Check record')}>▣ <span>Truck Inventory</span></button><button onClick={()=>show('Equipment prep is driven by assigned jobs')}>▤ <span>Equipment Prep</span></button><button onClick={()=>show((isService?'Service handoffs':'IT → Service handoffs')+' appear in Today’s Jobs')}>⌁ <span>Handoffs</span></button><button onClick={()=>window.location.assign('?workspace=camera-health')}>◉ <span>Camera Health</span></button></nav>
    </aside>
    <main className='it-main'>
      <header className='it-welcome'><div><h1>Good Morning, <i>{first}</i></h1><small>{departmentLabel} TECHNICIAN DASHBOARD</small></div><div className='it-clock'><b>{now.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',year:'numeric'})}</b><strong>{now.toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}</strong></div></header>
      {readiness&&<section className='it-readiness-block'><div><small>DAILY READINESS REQUIRED</small><h2>{readiness.command?.title||'Complete Truck Check'}</h2><p>{readiness.command?.section||'Truck Check'} · Jobs remain locked until morning readiness is complete.</p></div><div className='it-readiness-actions'>{readiness.command?.type==='start'&&<button disabled={busy} onClick={readiness.start}>START TRUCK CHECK</button>}{readiness.command?.type==='yes_no'&&<><button disabled={busy} onClick={()=>readiness.answer(true)}>YES</button><button className='danger' disabled={busy} onClick={()=>readiness.answer(false)}>NO</button></>}{readiness.command?.type==='number'&&<button disabled={busy} onClick={readiness.enterNumber}>ENTER QUANTITY</button>}{readiness.command?.type==='text'&&<button disabled={busy} onClick={readiness.enterText}>ENTER IDENTIFIER</button>}{readiness.command?.type==='choice'&&(readiness.command?.choices||[]).map((x:string)=><button disabled={busy} key={x} onClick={()=>readiness.answer(x)}>{x.toUpperCase()}</button>)}{readiness.command?.type==='ready_to_complete'&&<button disabled={busy} onClick={readiness.finish}>FINISH TRUCK CHECK</button>}</div></section>}{readiness&&!isService&&truck?.id&&<section className='it-identifiers'><div className='it-panel-head'><h2>Assigned Truck Identifiers</h2><span>{identifiersComplete?'COMPLETE':'REQUIRED'}</span></div><p>Record the actual permanent-stock unit numbers and SIM numbers on this same Truck Check. These are required before IT readiness can be completed.</p><div className='it-identifier-grid'>{[['sniperUnit','Sniper unit #'],['rangerUnit','Ranger unit #'],['spotterUnit','Spotter unit #'],['solarSpotterUnit','Solar Spotter unit #'],['attSim','AT&T SIM #'],['verizonSim','Verizon SIM #'],['venderaSim','Vendera SIM #']].map(([key,label])=><label key={key}><span>{label}</span><input value={identifiers[key]||''} onChange={e=>setIdentifiers((p:any)=>({...p,[key]:e.target.value}))} placeholder={label}/></label>)}</div><button className='it-save-identifiers' disabled={busy||!identifiersComplete} onClick={()=>saveIdentifiers?.(identifiers)}>SAVE IDENTIFIERS</button></section>}
      <section className='it-kpis'>
        <article><span>▣</span><div><b>{openTasks.length}</b><strong>Owner Tasks</strong><small>{high} high priority</small></div></article>
        <article><span>▤</span><div><b>{visits.length}</b><strong>Scheduled Jobs</strong><small>Today</small></div></article>
        <article><span>⌁</span><div><b>{handoffCount}</b><strong>{isService?'Service Handoffs':'IT → Service'}</strong><small>Handoffs / dependent work</small></div></article>
        <article className={truckReady?'good':'bad'}><span>▣</span><div><strong>Truck</strong><b>{truckReady?'READY':'NEEDS ATTENTION'}</b><small>{safetyChecks}/8 safety checks recorded</small></div></article>
        <article className='good camera-health-kpi' onClick={()=>window.location.assign('?workspace=camera-health')}><span>◉</span><div><strong>Camera Health</strong><b>OPEN IN COS</b><small>Live status inside COS Operations</small></div></article>
      </section>
      <section className='it-grid'>
        <article className='it-panel'><div className='it-panel-head'><h2>▣ Owner Tasks for Today</h2><span>{openTasks.length}</span></div><div className='it-table it-tasks'><div className='it-row head'><span>PRIORITY</span><span>TASK</span><span>RELATED TO</span><span>DUE</span><span>STATUS</span></div>{(tasks||[]).length?(tasks||[]).map((t:any)=><div className='it-row' key={t.id}><span><b className={'priority '+t.priority}>{String(t.priority).toUpperCase()}</b></span><span><strong>{t.title}</strong>{t.instructions&&<small>{t.instructions}</small>}</span><span>{t.jobNumber||t.siteName||'General'}</span><span className={t.dueAt&&new Date(t.dueAt)<now&&t.status!=='complete'?'overdue':''}>{t.dueAt?new Date(t.dueAt).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}):'—'}</span><span><button disabled={busy||t.status==='complete'} onClick={()=>updateTask(t.id,t.status==='not_started'?'in_progress':'complete')}>{taskStatus(t)}</button></span></div>):<div className='it-empty'>No Owner Tasks assigned today.</div>}</div></article>
        <article className='it-panel'><div className='it-panel-head'><h2>▤ Today’s Jobs</h2><span>{visits.length}</span></div><div className='it-table it-jobs'><div className='it-row head'><span>TIME</span><span>CUSTOMER / SITE</span><span>JOB #</span><span>TYPE</span><span>STATUS</span></div>{visits.length?visits.map((v:any)=><button className='it-row clickable' key={v.visit_id} disabled={busy||!truckReady} onClick={()=>truckReady?openVisit(v):show('Complete today’s Truck Check before opening jobs')}><span>{v.scheduled_start?new Date(v.scheduled_start).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}):'—'}</span><span><strong>{v.customer_name}</strong><small>{v.site_name}</small></span><span>{v.job_number}</span><span>{v.visit_type}</span><span><b className='job-pill'>{String(v.dispatch_status||v.status||'').replaceAll('_',' ')}</b></span></button>):<div className='it-empty'>No dispatched work today.</div>}</div></article>
        <article className='it-panel'><div className='it-panel-head'><h2>▣ {isService?'Truck / Trailer Stock & Readiness':'Truck Stock / Readiness'} — {first}</h2><b className={truckReady?'truck-good':'truck-bad'}>{truckReady?'TRUCK READY':'NEEDS ATTENTION'}</b></div><div className='truck-readiness'><div><span>Vehicle safety inspection</span><strong>{safetyChecks}/8</strong><b>{safetyChecks===8?'GOOD':'CHECK'}</b></div>{isService?<div><span>Service truck inventory</span><strong>{truckResult?.inventory?Object.keys(truckResult.inventory).length:'—'}</strong><b className='stock-note'>SEE TRUCK CHECK INVENTORY</b></div>:<><div className='stock-head'><span>ITEM</span><strong>REQUIRED / CURRENT</strong><b>STATUS</b></div>{itStock.map((x:any)=><div key={x[0]}><span>{x[0]}</span><strong>{x[1]} / {stockRecorded?x[2]:'—'}</strong><b className={stockRecorded&&x[2]<x[1]?'stock-short':'stock-good'}>{!stockRecorded?'NOT RECORDED':x[2]>=x[1]?'GOOD':'NEED '+(x[1]-x[2])}</b></div>)}</>}</div><p className='it-source-note'>Uses the existing production Truck Check record. Shortages automatically appear in Needs Attention.</p></article>
        <article className='it-panel'><div className='it-panel-head'><h2>⚠ Needs Attention</h2><span>{attention.length}</span></div><div className='it-table it-attention'><div className='it-row head'><span>TYPE</span><span>ISSUE</span><span>RELATED TO</span><span>PRIORITY</span></div>{attention.length?attention.map((a:any,i:number)=><div className='it-row' key={i}><span>{a.type}</span><span>{a.issue}</span><span>{a.related}</span><span><b className={'priority '+a.priority.toLowerCase()}>{a.priority}</b></span></div>):<div className='it-empty good-empty'>No actionable issues detected from the currently connected dashboard sources.</div>}</div></article>
      </section>
    </main>
  </div>;
}
